/**
 * 负责按身份、板子、动作、事件、结果与死亡概念聚合既有领域出口；输出保持原值／类型绑定。
 * 具体契约仍由各概念及 game-contract 拥有，这里不定义第二套枚举、状态或规则。
 * 原重导出顺序和下游模块加载关系保持；出口本身不创建角色、授予请求权限或封盘。
 */
export * from "./identity";
export * from "./board";
export * from "./actions";
export * from "./events";
export * from "./results";
export * from "./deaths";

/**
 * 负责公开杠精辩论禁票处罚的数据结构；输入为处罚日次、来源编号和捕获的生命版本。
 * 实际 record 引用与原 NightLifeScope 另由辩论 authority 保存并查询；这些数字不能重建其许可。
 * 接口字段保持可写，不冻结、安装、撤销或执行处罚；缺省日次和生命复验沿原运行查询。
 */
export interface DebatePenaltyComponent {
  /** 处罚所属日次；运行查询的 day 缺省接受面由 authority 决定，不在字段定义中统一到期。 */
  day: number;
  /** 原处罚来源的实体编号；不是请求 token，也不独立证明该来源当前存活或有权提交。 */
  sourceId: number;
  /** 记录捕获时的生命版本；真实当前性还依赖 authority 保存的原生命对象与组件引用。 */
  lifeVersion: number;
}

/**
 * 负责 core 的既有公共领域出口；输入为 domain 导出的类型、组件工厂、存储与运行端口，
 * 输出保持同一公开绑定，不复制实例、建立第二份状态或替原所有者授予权限。
 * 原重导出与其叶模块加载关系保持；具体初始化、副作用和生命周期仍归实际实现。
 */
export * from "./domain";

