/**
 * 负责实体 ID、组件 Map 与原生命绑定的临时死亡行动许可。输入为既有实体／槽操作及
 * 生命周期回调，输出保持原可写组件引用、筛选结果和许可 ID。World 唯一写入自己的存储，
 * 工厂与角色所有者仍负责值和资源校验；槽推断不增加运行守卫、复制或冻结。
 * 旧任意组件类型 T 重载已退出，读写关系由具名槽约束；死亡许可仍按原生命版本与当前性撤销，ID 本身不授权。
 */
import { EntityId, Phase, Role } from "./model";
import { COMPONENT, ComponentName } from "./components/names";
import type { ComponentMap, ComponentWrite } from "./component-map";
import { AliveComponent, aliveLifeVersion } from "./components/alive";
import { RoleComponent } from "./components/role";
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";

/**
 * World 是 ECS 内存状态容器。
 * 设计目标：保持结构简单、读写明确，所有系统都基于该容器进行组件查询与变更。
 */
export class World {
  constructor(readonly locale: Locale = "zh-CN") {
    if (!isLocale(locale)) throw new Error("game_locale_invalid");
  }
  private nextId: EntityId = 1;
  private entities: Set<EntityId> = new Set();
  private stores: Map<ComponentName, Map<EntityId, unknown>> = new Map();
  private nextDeathActionId = 1;
  // 许可绑定原 Alive 对象和该对象的生命版本；复活、替换组件或失去当前性均撤销旧许可。
  private deathActions = new Map<
    EntityId,
    {
      id: number;
      tool: "shoot" | "speak" | "choose_badge_successor";
      phase: Phase;
      day: number;
      abilityId?: string;
      alive: AliveComponent;
      lifeVersion: number;
      isCurrent: () => boolean;
    }
  >();

  /** 引擎拥有的临时行动许可；ID 不授予行动。World 复核原生命与传入的当前性回调，带阶段的查询另核许可记录的 phase／day。 */
  openDeathAction(
    actorId: EntityId,
    tool: "shoot" | "speak" | "choose_badge_successor",
    phase: Phase,
    day: number,
    isCurrent: () => boolean = () => true,
    abilityId?: string,
  ): { readonly id: number; close(): void } {
    if (this.currentDeathAction(actorId)) throw new Error("death_action_already_open");
    const alive = this.getComponent(actorId, COMPONENT.Alive);
    const lifeVersion = alive && aliveLifeVersion(alive);
    if (
      !alive ||
      alive.alive !== false ||
      lifeVersion === undefined ||
      !this.getComponent(actorId, COMPONENT.Role) ||
      !Number.isSafeInteger(day) ||
      day < 1 ||
      !["shoot", "speak", "choose_badge_successor"].includes(tool) ||
      !Object.values(Phase).includes(phase) ||
      phase === Phase.GameOver ||
      (abilityId !== undefined &&
        (tool !== "shoot" ||
          typeof abilityId !== "string" ||
          !/^[a-z][a-z0-9:_-]{0,127}$/.test(abilityId) ||
          abilityId.startsWith("native:")))
    ) {
      throw new Error("death_action_invalid_actor_or_stage");
    }
    const id = this.nextDeathActionId++;
    this.deathActions.set(actorId, {
      id,
      tool,
      phase,
      day,
      abilityId,
      alive,
      lifeVersion,
      isCurrent,
    });
    return Object.freeze({
      id,
      close: () => {
        if (this.deathActions.get(actorId)?.id === id) this.deathActions.delete(actorId);
      },
    });
  }

  hasDeathAction(
    actorId: EntityId,
    tool: string,
    phase: Phase,
    day: number | undefined,
    id: number | undefined,
    abilityId?: string,
  ): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.phase === phase &&
      permit.day === day &&
      permit.abilityId === abilityId
    );
  }

  isDeathActionOpen(actorId: EntityId, tool: string, id: number, abilityId?: string): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.abilityId === abilityId
    );
  }

  private currentDeathAction(actorId: EntityId) {
    const permit = this.deathActions.get(actorId);
    if (!permit) return undefined;
    if (
      this.getComponent(actorId, COMPONENT.Alive) !== permit.alive ||
      permit.alive.alive !== false ||
      aliveLifeVersion(permit.alive) !== permit.lifeVersion ||
      !permit.isCurrent()
    ) {
      this.deathActions.delete(actorId);
      return undefined;
    }
    return permit;
  }

  get activeDeathActionCount(): number {
    for (const actorId of this.deathActions.keys()) this.currentDeathAction(actorId);
    return this.deathActions.size;
  }

  closeDeathActions(): void {
    this.deathActions.clear();
  }

  /**
   * 创建新实体并返回实体 ID。
   */
  createEntity(): EntityId {
    const id = this.nextId++;
    this.entities.add(id);
    return id;
  }

  /**
   * 判断实体是否存在。
   */
  hasEntity(entityId: EntityId): boolean {
    return this.entities.has(entityId);
  }

  /**
   * 返回当前所有实体 ID（升序）。
   */
  entityIds(): EntityId[] {
    return [...this.entities].sort((a, b) => a - b);
  }

  addComponent<K extends ComponentName, C extends ComponentWrite<NoInfer<K>>>(
    entityId: EntityId,
    name: K,
    component: C,
  ): void {
    if (!this.hasEntity(entityId)) {
      throw new Error(`Entity ${entityId} does not exist`);
    }

    // 每类组件一张表，按 entityId 索引。
    const store = this.ensureStore(name);
    store.set(entityId, component);
  }

  getComponent<K extends ComponentName>(entityId: EntityId, name: K): ComponentMap[K] | undefined {
    const store = this.stores.get(name);
    return store?.get(entityId) as ComponentMap[K] | undefined;
  }

  /**
   * 从实体上移除指定组件。
   */
  removeComponent(entityId: EntityId, name: ComponentName): void {
    const store = this.stores.get(name);
    store?.delete(entityId);
  }

  /**
   * 返回同时拥有给定组件集合的实体列表。
   */
  entitiesWith(...names: ComponentName[]): EntityId[] {
    // 只有同时拥有所有组件的实体才会被返回，用于系统筛选。
    return this.entityIds().filter((entityId) => {
      return names.every((name) => {
        const store = this.stores.get(name);
        return store?.has(entityId) ?? false;
      });
    });
  }

  /**
   * 返回当前存活实体 ID 列表。
   */
  getAliveEntityIds(): EntityId[] {
    return this.entitiesWith(COMPONENT.Alive).filter((id) => {
      const alive = this.getComponent(id, COMPONENT.Alive);
      return alive?.alive === true;
    });
  }

  /**
   * 按角色筛选实体 ID。
   */
  getEntityIdsByRole(role: Role): EntityId[] {
    return this.entitiesWith(COMPONENT.Role).filter((id) => {
      const roleComp = this.getComponent(id, COMPONENT.Role);
      return roleComp?.role === role;
    });
  }

  /**
   * 确保组件存储存在，不存在则懒加载创建。
   */
  private ensureStore(name: ComponentName): Map<EntityId, unknown> {
    let store = this.stores.get(name);
    if (!store) {
      // 延迟初始化组件存储，避免为未使用组件提前分配空间。
      store = new Map<EntityId, unknown>();
      this.stores.set(name, store);
    }
    return store;
  }
}

/**
 * 负责按演员生命、角色、可信行动窗口及已注册规则校验工具调用。输入为已清洗调用及校验上下文，输出为原规则结果与配置的校验 trace。
 * 领域预检通过不等于库存付款，本模块不以 schema 接受代替实际资源提交。
 */
import { RuleError, type RuleViolation } from "@ai-werewolf-arena/game-contract";
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { AliveComponent } from "../../core/domain/components/alive";
import { COMPONENT } from "../../core/domain/components/names";
import { RoleComponent } from "../../core/domain/components/role";
import {
  ActionWindow,
  EntityId,
  Phase,
  ToolCall,
  ToolValidationResult,
} from "../../core/domain/model";
import { getDefaultToolValidationRuleRegistry, ToolValidationRuleRegistry } from "../mechanisms";
import { safeRecordLogicOp } from "../../recording/session_recorder";
import { World } from "../../core/domain/world";

/**
 * 动作校验上下文。
 */
export interface ValidationContext {
  /** 有事务归属的 controller 只在实际提交后记录校验。 */
  deferOperation?: boolean;
  day?: number;
  thiefScope?: object;
  shapeshifterScope?: object;
  wildChildScope?: object;
  lonelyGirlScope?: object;
  ghostBrideScope?: object;
  demonHunterScope?: object;
  nobleBodyScope?: object;
  fragrantPairScope?: object;
  animalScope?: object;
  wallScope?: object;
  wallId?: string;
  itemInstanceId?: string;
  debateId?: string;
  abilityId?: string;
  phase: Phase;
  actionWindow?: ActionWindow;
  allowSelfDestruct?: boolean;
  duelWindow?: import("../../core/domain/identity").KnightDuelWindow;
  allowKnightDuel?: boolean;
  deathActionId?: number;
  sheriffCandidates?: readonly EntityId[];
  badgeCandidates?: readonly EntityId[];
  exileCandidates?: readonly EntityId[];
}

/**
 * ActionValidator 是“规则防线”。
 * 所有模型工具调用在落地前都必须通过这里，非法动作统一返回错误并要求重试。
 */
export class ActionValidator {
  constructor(
    private readonly ruleRegistry: ToolValidationRuleRegistry = getDefaultToolValidationRuleRegistry(),
    private readonly recordOperations = true,
  ) {}

  validate<T extends ToolCall>(
    world: World,
    actorId: EntityId,
    toolCall: T,
    context: ValidationContext,
  ): ToolValidationResult<T> {
    const reject = (violation: RuleViolation): ToolValidationResult<T> => {
      if (this.recordOperations && context.deferOperation !== true)
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId,
          phase: context.phase,
          status: "rejected",
          reason: violation.code,
          input: {
            tool: toolCall.name,
            args: (toolCall as any).args ?? {},
            action_window: context.actionWindow,
          },
        });
      return toolFailure(world.locale, violation.code, violation.message);
    };
    const accept = (): ToolValidationResult<T> => {
      if (this.recordOperations && context.deferOperation !== true)
        safeRecordLogicOp({
          scope: "gateway",
          op: "validate_tool_call",
          actorId,
          phase: context.phase,
          status: "ok",
          input: {
            tool: toolCall.name,
            args: (toolCall as any).args ?? {},
            action_window: context.actionWindow,
          },
        });
      return {
        ok: true,
        sanitizedCall: toolCall,
      };
    };

    const role = world.getComponent(actorId, COMPONENT.Role);
    const alive = world.getComponent(actorId, COMPONENT.Alive);

    if (!role || !alive) {
      return reject({ code: RuleError.ActorMissing });
    }

    const allowDeadAction = world.hasDeathAction(
      actorId,
      toolCall.name,
      context.phase,
      context.day,
      context.deathActionId,
      context.abilityId,
    );
    if (context.deathActionId !== undefined && (alive.alive || !allowDeadAction)) {
      return reject({ code: RuleError.DeathActionUnavailable });
    }
    if (!alive.alive && !allowDeadAction) {
      return reject({ code: RuleError.ActorDead });
    }
    if (toolCall.name === "choose_badge_successor" && (alive.alive || !allowDeadAction))
      return reject({ code: RuleError.DeathActionUnavailable });
    if (toolCall.name === "shoot" && (alive.alive || !allowDeadAction)) {
      return reject({ code: RuleError.ShootUnavailable });
    }

    const error = this.ruleRegistry.validate({
      world,
      actorId,
      role,
      toolCall,
      phase: context.phase,
      day: context.day,
      thiefScope: context.thiefScope,
      shapeshifterScope: context.shapeshifterScope,
      wildChildScope: context.wildChildScope,
      lonelyGirlScope: context.lonelyGirlScope,
      ghostBrideScope: context.ghostBrideScope,
      demonHunterScope: context.demonHunterScope,
      nobleBodyScope: context.nobleBodyScope,
      fragrantPairScope: context.fragrantPairScope,
      animalScope: context.animalScope,
      wallScope: context.wallScope,
      wallId: context.wallId,
      itemInstanceId: context.itemInstanceId,
      debateId: context.debateId,
      abilityId: context.abilityId,
      actionWindow: context.actionWindow,
      allowSelfDestruct: context.allowSelfDestruct,
      duelWindow: context.duelWindow,
      allowKnightDuel: context.allowKnightDuel,
      sheriffCandidates: context.sheriffCandidates,
      exileCandidates: context.exileCandidates,
      badgeCandidates: context.badgeCandidates,
    });
    if (error) {
      return reject(error);
    }

    return accept();
  }
}

/**
 * 负责杠精辩论窗口、一次提交登记及原生命绑定的禁票处罚。输入为原参与者和已校验选择，
 * 输出为窗口、提交及处罚查询；参与者捕获／复验归中立数据所有者，不在此复制其政策。
 * 不变量：关闭仅退休同一窗口；原已提交选择不退款，处罚仍在实际查询时按原生命版本失效。
 */
import {
  COMPONENT,
  type World,
  type DebatePenaltyComponent,
} from "../../../../core/domain";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";

import type { OriginalParticipant as DebateParticipant } from "../../../../core/domain/original-participant";

export interface DebateAuthority {
  id: string;
  day: number;
  actorId: number;
  targetId: number;
  stage: "challenge" | "speech" | "ballot";
  participants: ReadonlyMap<number, DebateParticipant>;
}
const active = new WeakMap<World, DebateAuthority>();
export function hasActiveDebate(world: World): boolean {
  return active.has(world);
}
const sequences = new WeakMap<World, number>();
export function nextDebateId(world: World, day: number, actorId: number, targetId: number): string {
  if (active.has(world)) throw new Error("debate_window_reentry");
  const sequence = (sequences.get(world) ?? 0) + 1;
  sequences.set(world, sequence);
  return `debate:${day}:${actorId}:${targetId}:${sequence}`;
}
const commits = new WeakMap<World, Set<number>>();
const penalties = new WeakMap<
  World,
  Map<number, { record: DebatePenaltyComponent; life: NightLifeScope }>
>();
export function openDebate(world: World, authority: DebateAuthority): void {
  if (active.has(world)) throw new Error("debate_window_reentry");
  active.set(world, authority);
}
export function closeDebate(world: World, authority: DebateAuthority): void {
  if (active.get(world) === authority) active.delete(world);
}
export function debateAuthority(world: World, token: string | undefined): DebateAuthority | null {
  const a = active.get(world);
  return a && a.id === token ? a : null;
}
export function hasDebateCommit(world: World, id: number): boolean {
  return commits.get(world)?.has(id) === true;
}
export function commitDebate(world: World, id: number): void {
  if (hasDebateCommit(world, id)) throw new Error("debate_already_committed");
  let ids = commits.get(world);
  if (!ids) {
    ids = new Set();
    commits.set(world, ids);
  }
  ids.add(id);
}
export function blockDebateVote(world: World, id: number, sourceId: number, day: number): void {
  const life = captureNightLife(world, id);
  if (!life) return;
  const record: DebatePenaltyComponent = { day, sourceId, lifeVersion: life.version };
  let entries = penalties.get(world);
  if (!entries) {
    entries = new Map();
    penalties.set(world, entries);
  }
  entries.set(id, { record, life });
  world.addComponent(id, COMPONENT.DebatePenalty, record);
}
export function debateVoteBlocked(world: World, id: number, day: number | undefined): boolean {
  const b = penalties.get(world)?.get(id);
  return (
    !!b &&
    (day === undefined || b.record.day === day) &&
    world.getComponent(id, COMPONENT.DebatePenalty) === b.record &&
    livingNightLife(world, b.life)
  );
}

/**
 * 负责胜利条件的有序委托与覆盖结果优先选择。输入为原 World、只读条件 ID、检查点及覆盖数据；输出为首个原判定或 null。
 * 本入口不改变参数数组或封存结果，真实检查点执行与终局仍由 PhaseManager 持有。
 */
import type { VictoryCheckpoint } from "@ai-werewolf-arena/game-contract";
import { WinDecision, WinCondition } from "../model";
import { World } from "../world";

/**
 * 胜负判定注册中心抽象：由机制层实现并在装配期注入。
 */
export interface WinConditionEvaluator {
  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null;
}

/**
 * 胜负条件入口：委托机制层 WinConditionRegistry。
 */
export class ConditionRegistry {
  private readonly winRegistry: WinConditionEvaluator;

  constructor(winRegistry: WinConditionEvaluator) {
    this.winRegistry = winRegistry;
  }

  /**
   * 按指定胜负模式执行胜负判定。
   */
  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null {
    return this.winRegistry.evaluate(world, condition, checkpoint);
  }

  /**
   * 按给定顺序评估多个胜负模式，命中即返回。
   */
  evaluateMany(
    world: World,
    conditions: readonly WinCondition[],
    checkpoint?: VictoryCheckpoint,
    overrides: Partial<Record<WinCondition, WinDecision>> = {},
  ): WinDecision | null {
    for (const condition of conditions) {
      const result = overrides[condition] ?? this.evaluate(world, condition, checkpoint);
      if (result) {
        return result;
      }
    }
    return null;
  }
}
